        val id: String,
        val state: String,
        val agents: Long,
    ) : RemoteThreadItem

    @Serializable
    @SerialName("completed")
    data class Completed(
        val id: String,
        val status: String,
        val errorCode: String? = null,
    ) : RemoteThreadItem
}
